// PR Detection — Brainstorm §5 trigger #5.
// Cron-poll every 15 minutes: scan workout_log_exercises rows with is_pr=true
// inserted in the last 20 minutes (15min interval + 5min buffer for cron drift).
// Group PRs by user, send ONE notification per user mentioning their PR(s).
// Both free + PRO. Dedup via coach_memory.last_proactive_type (1/day max).
// Cron target: */15 * * * * (every 15 min). Registration deferred to T6.

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import { sendPushNotification } from "../_shared/send_notification.ts";
import {
  markProactiveSent,
  shouldSendProactive,
} from "../_shared/proactive_dedup.ts";
import { fetchCoachMemory } from "../_shared/coach_memory.ts";
import { captainPrompt } from "../_shared/captain_manual.ts";
import { geminiChat, MODEL_FLASH } from "../_shared/gemini.ts";
import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
import { sanitizeIdentifier, sanitizeJsonForPrompt } from "../_shared/sanitize_for_prompt.ts";
import { logCronStart, logCronEnd } from "../_shared/cron_telemetry.ts";
import { fetchAllPages } from "../_shared/paged_fetch.ts";
import {
  fetchNotificationPrefs,
  isNotificationEnabled,
} from "../_shared/notification_prefs.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

interface PRRow {
  user_id: string;
  exercise_id: string; // = exercise name per docs/architecture/ai.md
  weight_kg: number | null;
  reps: number | null;
  completed_at: string; // F43: real workout time, not row sync time
}

// Audit C-4 (2026-05-11, closes-diagnose 7ad0c4): added CRON_SECRET / service-role-key gate.
Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  // ── Audit 2026-05-16 / E.14.C — JWT signature + role-claim auth.
  //
  // Was: inline env-equality `token === SUPABASE_SERVICE_ROLE_KEY`. That
  // shape silently 401-stormed when the Vault-stored JWT and the env-
  // injected SUPABASE_SERVICE_ROLE_KEY drifted (Test #16 P1-D root
  // cause). New: verify the JWT signature against SUPABASE_JWT_SECRET and
  // require `role === 'service_role'`. CRON_SECRET opaque-token path is
  // preserved inside the helper as escape hatch.
  if (!await isAuthorizedCronCall(req)) {
    console.warn(`[cron-auth-gate] unauthorized caller; status=401`);
    return new Response(
      JSON.stringify({ error: "Unauthorized" }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }

  const requestId = crypto.randomUUID().split("-")[0];
  const logId = await logCronStart("pr-detection");

  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    // Window: last 20 minutes (15min cron + 5min buffer).
    // F43 (2026-06-07 audit): filter/order by `completed_at` — the real
    // workout time — NOT `created_at` (row sync time). An offline workout
    // synced days later carries a fresh created_at; filtering on it fired a
    // stale "New PR!" push for a lift the user set days ago. completed_at is
    // when the workout actually happened, so the recency window is honest.
    const since = new Date(Date.now() - 20 * 60_000).toISOString();

    // OI-79: paged. `completed_at` alone was NOT a safe page key — it is not
    // unique (a whole workout's exercises share one timestamp), so ties could
    // shuffle between page requests and drop or duplicate a PR. `id` is added as
    // the unique tiebreaker; completed_at DESC stays first so the existing
    // newest-first ordering the grouping below relies on is unchanged.
    const rows = await fetchAllPages<PRRow>(
      () =>
        supabase
          .from("workout_log_exercises")
          .select("user_id, exercise_id, weight_kg, reps, completed_at")
          .eq("is_pr", true)
          .gte("completed_at", since),
      {
        orderBy: [
          { column: "completed_at", ascending: false },
          { column: "id", ascending: true },
        ],
        label: "pr-detection prs",
      },
    );

    if (!rows || rows.length === 0) {
      console.log(
        `[pr-detection] request_id=${requestId} no PRs in window`,
      );
      await logCronEnd(logId, "success", { httpStatus: 200, requestId });
      return new Response(JSON.stringify({ checked: 0, sent: 0 }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Group PRs by user
    const prsByUser = new Map<string, PRRow[]>();
    for (const row of rows as PRRow[]) {
      if (!prsByUser.has(row.user_id)) prsByUser.set(row.user_id, []);
      prsByUser.get(row.user_id)!.push(row);
    }

    // Unit E — one batched, latest-desc read for the whole run (NOT
    // today-pinned; see _shared/notification_prefs.ts for why that shape is
    // inert against live data).
    const notifPrefs = await fetchNotificationPrefs(
      supabase,
      [...prsByUser.keys()],
    );

    let sent = 0;
    let dedupSkipped = 0;
    let prefsOff = 0;
    let errors = 0;

    for (const [userId, prs] of prsByUser.entries()) {
      // User turned PR celebrations off. Checked BEFORE the dedup gate so an
      // opted-out user does not burn their one-per-day proactive slot on a
      // push that is then discarded, which would suppress a different
      // notification they still want.
      if (!isNotificationEnabled(notifPrefs, userId, "pr_celebration")) {
        prefsOff++;
        continue;
      }

      // Dedup gate
      if (!(await shouldSendProactive(supabase, userId, "pr_celebration"))) {
        dedupSkipped++;
        continue;
      }

      // Personalization
      const memory = await fetchCoachMemory(supabase, userId);
      const usableMemory = memory?.private_mode ? null : memory;
      // OI-47 round 1: firstName feeds composeMessage(), which builds the
      // FALLBACK push that actually ships when Gemini fails.
      const firstName = sanitizeIdentifier(
        usableMemory?.preferred_name as string | null,
        { fallback: "champ", maxLen: 32 },
      );

      // Fallback: existing hardcoded English copy preserved as safety net.
      const fallbackMessage = composeMessage(firstName, prs);

      // Generate Captain-voiced copy via Gemini; fall back to English on error.
      let message = fallbackMessage;
      try {
        const prSummary = prs.slice(0, 3).map((p) => ({
          exercise: p.exercise_id,
          weight_kg: p.weight_kg,
          reps: p.reps,
        }));
        const userState = {
          first_name: firstName,
          new_prs: prSummary,
          total_pr_count: prs.length,
        };
        const { content } = await geminiChat({
          model: MODEL_FLASH,
          systemPrompt: captainPrompt("proactive"),
          userPrompt:
            `User state: ${sanitizeJsonForPrompt(userState)}.\n\n` +
            `Generate a PR celebration nudge — user just set ${prs.length} new ` +
            `personal record(s) in their workout.`,
          maxTokens: 120,
          temperature: 0.7,
        });
        if (content && content.trim().length > 0) {
          message = content.trim();
        }
      } catch (e) {
        console.warn(
          `[pr-detection] Gemini failed for ${userId}, using fallback copy: ${e}`,
        );
      }

      try {
        const ok = await sendPushNotification({
          userId,
          title: prs.length === 1 ? "New PR! 🏆" : `${prs.length} new PRs! 🏆`,
          message,
          screen: "/train",
        });
        if (ok) {
          sent++;
          await markProactiveSent(supabase, userId, "pr_celebration");
        } else {
          errors++;
        }
      } catch (e) {
        console.warn(`[pr-detection] send failed for ${userId}:`, e);
        errors++;
      }
    }

    console.log(
      `[pr-detection] request_id=${requestId} pr_rows=${rows.length} users=${prsByUser.size} sent=${sent} prefs_off=${prefsOff} dedup_skipped=${dedupSkipped} errors=${errors}`,
    );

    await logCronEnd(logId, "success", { httpStatus: 200, requestId });
    return new Response(
      JSON.stringify({
        pr_rows: rows.length,
        users: prsByUser.size,
        sent,
        prefs_off: prefsOff,
        dedup_skipped: dedupSkipped,
        errors,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (err) {
    console.error(`[pr-detection] request_id=${requestId}`, err);
    await logCronEnd(logId, "failed", {
      httpStatus: 500,
      requestId,
      errorSummary: String(err),
    });
    return new Response(
      JSON.stringify({ error: "Internal server error", request_id: requestId }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  }
});

/** Build a single-line celebratory message from up to 2 PRs (+N more). */
function composeMessage(firstName: string, prs: PRRow[]): string {
  if (prs.length === 0) return "";

  const fmt = (p: PRRow) => {
    const weight = p.weight_kg ?? 0;
    const reps = p.reps ?? 0;
    if (weight > 0) {
      return `${p.exercise_id} ${weight}kg`;
    }
    return `${p.exercise_id} ${reps} reps`;
  };

  if (prs.length === 1) {
    return `${firstName} — new ${fmt(prs[0])} PR. Want to bump next week's target?`;
  }
  if (prs.length === 2) {
    return `${firstName} — new PRs: ${fmt(prs[0])}, ${fmt(prs[1])}. Strong session.`;
  }
  // 3+ PRs
  const tail = prs.length - 2;
  return `${firstName} — new PRs: ${fmt(prs[0])}, ${fmt(prs[1])} +${tail} more. Strong session.`;
}

/**
 * Shared OneSignal push notification helper.
 *
 * Used by all cron Edge Functions (streak-guardian, expiry-reminder,
 * morning-alert, weekly-recap-ready) to send push notifications.
 *
 * Requires ONESIGNAL_APP_ID and ONESIGNAL_REST_API_KEY env vars.
 */

const ONESIGNAL_APP_ID = Deno.env.get("ONESIGNAL_APP_ID")!;
const ONESIGNAL_REST_API_KEY = Deno.env.get("ONESIGNAL_REST_API_KEY")!;

export interface PushNotificationParams {
  /** Supabase user UUID (mapped to OneSignal external_id). */
  userId: string;
  /** Notification title (bold heading). */
  title: string;
  /** Notification body message. */
  message: string;
  /** Optional deep-link screen path (e.g., '/train', '/profile'). */
  screen?: string;
}

/**
 * Send a push notification to a single user via OneSignal.
 *
 * Uses `include_aliases` with `external_id` targeting, which maps
 * to the Supabase UUID set via `OneSignal.login(user.id)` on the
 * Flutter client.
 *
 * @returns true if the API call succeeded (2xx), false otherwise.
 */
export async function sendPushNotification({
  userId,
  title,
  message,
  screen,
}: PushNotificationParams): Promise<boolean> {
  if (!ONESIGNAL_APP_ID || !ONESIGNAL_REST_API_KEY) {
    console.warn("OneSignal credentials not configured — skipping push.");
    return false;
  }

  try {
    const payload: Record<string, unknown> = {
      app_id: ONESIGNAL_APP_ID,
      include_aliases: { external_id: [userId] },
      target_channel: "push",
      headings: { en: title },
      contents: { en: message },
    };

    if (screen) {
      payload.data = { screen };
    }

    const response = await fetch(
      "https://onesignal.com/api/v1/notifications",
      {
        method: "POST",
        headers: {
          Authorization: `Basic ${ONESIGNAL_REST_API_KEY}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      },
    );

    if (!response.ok) {
      const errorBody = await response.text();
      console.error(
        `OneSignal push failed for user ${userId}: ${response.status} — ${errorBody}`,
      );
      return false;
    }

    return true;
  } catch (err) {
    console.error(`OneSignal push error for user ${userId}:`, err);
    return false;
  }
}

/**
 * Shared dedup helper for proactive notification triggers.
 *
 * Brainstorm §5 rule: "Never repeat same trigger type two days in a row."
 * Implementation: each function calls shouldSendProactive(supabase, userId, type)
 * BEFORE sending, and markProactiveSent(supabase, userId, type) AFTER successful push.
 *
 * Trigger types (canonical strings — keep in sync with the matrix):
 *   morning_brief, workout_window, protein_gap, streak_protection,
 *   pr_celebration, plateau_alert, weekly_recap, re_engagement,
 *   subscription_expiry
 *
 * Dedup window: same calendar day in IST (the app's primary timezone).
 * Stored as ISO timestamp + type string in coach_memory; we compare
 * IST date components.
 */

import { fetchCoachMemory, upsertCoachMemory } from "./coach_memory.ts";

export type ProactiveType =
  | "morning_brief"
  | "workout_window"
  | "protein_gap"
  | "streak_protection"
  | "pr_celebration"
  | "plateau_alert"
  | "weekly_recap"
  | "re_engagement"
  | "subscription_expiry"
  // Unit G — added so the vocabulary is complete and the notification key
  // `rank_promotion` is canonical rather than an ad-hoc payload string.
  //
  // DELIBERATELY NOT DAY-DEDUPED. proactive-coach-promotion must NOT call
  // markProactiveSent with this type. `shouldSendProactive` compares a SINGLE
  // `last_proactive_type` slot, so stamping a promotion would overwrite
  // whatever was last sent — and a pr_celebration already sent that day would
  // then pass the `lastType !== type` check and fire AGAIN. Adding a rare event
  // to the chain would weaken dedup for the frequent ones.
  //
  // Nothing is lost: a promotion is trigger-fired once per rank change, so it
  // is one-per-event by construction and needs no day gate. (round-3 F8)
  | "rank_promotion";

/**
 * Returns true if this proactive type can be sent now (i.e. NOT already
 * sent today in IST). Respects coach_memory.private_mode by ALWAYS allowing
 * sends — private_mode only suppresses personalization in copy, not the
 * fact of sending operationally important nudges.
 *
 * Returns true ALSO when coach_memory row doesn't exist yet (new user) —
 * we want them to receive their first nudge.
 */
export async function shouldSendProactive(
  // deno-lint-ignore no-explicit-any
  supabase: any,
  userId: string,
  type: ProactiveType,
): Promise<boolean> {
  try {
    const memory = await fetchCoachMemory(supabase, userId);
    if (!memory) return true; // new user — allow

    const lastType = memory.last_proactive_type as string | null | undefined;
    const lastAt = memory.updated_at as string | null | undefined;
    if (!lastType || !lastAt) return true;
    if (lastType !== type) return true; // different type — fine to send

    // Same type — check if it was today in IST
    return !isSameISTDate(lastAt, new Date().toISOString());
  } catch (e) {
    // Defensive: dedup failure should never block a nudge.
    console.warn(`[proactive_dedup] shouldSend check failed for ${userId}/${type}:`, e);
    return true;
  }
}

/**
 * Records that a proactive of this type was just sent. Updates
 * coach_memory.last_proactive_type. Non-fatal on failure (the push
 * already went out).
 */
export async function markProactiveSent(
  // deno-lint-ignore no-explicit-any
  supabase: any,
  userId: string,
  type: ProactiveType,
): Promise<void> {
  try {
    await upsertCoachMemory(supabase, userId, {
      last_proactive_type: type,
    });
  } catch (e) {
    console.warn(`[proactive_dedup] markSent failed for ${userId}/${type}:`, e);
  }
}

/** Returns true if both ISO timestamps fall on the same calendar date in IST (UTC+5:30). */
function isSameISTDate(a: string, b: string): boolean {
  const da = new Date(a);
  const db = new Date(b);
  // IST = UTC + 5:30 → add 5*60+30 = 330 minutes
  const aIst = new Date(da.getTime() + 330 * 60_000);
  const bIst = new Date(db.getTime() + 330 * 60_000);
  return (
    aIst.getUTCFullYear() === bIst.getUTCFullYear() &&
    aIst.getUTCMonth() === bIst.getUTCMonth() &&
    aIst.getUTCDate() === bIst.getUTCDate()
  );
}

// supabase/functions/_shared/coach_memory.ts
// Shared accessors for the coach_memory table. Used by ai-proxy,
// daily-snapshot, compute-coach-signals, morning-alert.

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";
import {
  sanitizeIdentifier,
  sanitizeJsonForPrompt,
} from "./sanitize_for_prompt.ts";

export interface CoachMemory {
  user_id: string;
  preferred_name: string | null;
  communication_style: "hinglish" | "english" | "formal" | "casual" | null;
  humor_tolerance: "high" | "low" | "none" | null;
  depth_preference: "explanation_seeker" | "action_taker" | null;
  motivation_style: "tough_love" | "gentle" | "data_driven" | null;
  injuries: unknown[];
  food_preferences: Record<string, unknown>;
  equipment_notes: string | null;
  excuse_patterns: unknown[];
  lifestyle: Record<string, unknown>;
  supplement_stack: unknown[];
  peak_activity_hour: number | null;
  weak_day: string | null;
  cheat_day_pattern: string | null;
  dropout_risk_score: number | null;
  plateau_risk_score: number | null;
  pro_upgrade_probability: number | null;
  signals_computed_at: string | null;
  last_proactive_type: string | null;
  last_extraction_at: string | null;
  consent_version: string;
  private_mode: boolean;
  coach_notes: string | null;
  updated_at: string;
}

export type CoachMemoryPatch = Partial<Omit<CoachMemory, "user_id" | "updated_at">>;

export async function fetchCoachMemory(
  supabase: SupabaseClient,
  userId: string,
): Promise<CoachMemory | null> {
  const { data, error } = await supabase
    .from("coach_memory")
    .select("*")
    .eq("user_id", userId)
    .maybeSingle();
  if (error) {
    console.error("[coach_memory.fetch] error:", error.message);
    return null;
  }
  return (data as CoachMemory) ?? null;
}

export async function upsertCoachMemory(
  supabase: SupabaseClient,
  userId: string,
  patch: CoachMemoryPatch,
): Promise<void> {
  // Strip undefined so we don't overwrite existing values with NULL.
  const cleanPatch: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(patch)) {
    if (v !== undefined) cleanPatch[k] = v;
  }
  if (Object.keys(cleanPatch).length === 0) return;

  const { error } = await supabase
    .from("coach_memory")
    .upsert({ user_id: userId, ...cleanPatch }, { onConflict: "user_id" });
  if (error) {
    console.error("[coach_memory.upsert] error:", error.message);
    throw error;
  }
}

/**
 * Tone guidance keyed by motivation_style.
 *
 * A Map rather than an object literal DELIBERATELY: object-literal indexing with
 * an unvalidated key reaches inherited members ("constructor", "toString", ...).
 * Found by review round 2.
 */
const _TONE_GUIDANCE = new Map<string, string>([
  ["tough_love", "be direct, no soft padding"],
  ["gentle", "be warm and validating before suggesting"],
  ["data_driven", "lead with the number, then the suggestion"],
]);

/**
 * Renders the coach_memory row as a system-prompt fragment (block [3]
 * of the 7-block context layout). Returns empty string when row is null
 * or private_mode is on.
 */
export function renderCoachMemoryBlock(mem: CoachMemory | null): string {
  if (!mem || mem.private_mode) return "";

  // OI-47 P0 (review round 1, 2026-07-27). THIS BLOCK IS CONCATENATED INTO THE
  // SYSTEM PROMPT of every ai-proxy chat turn (ai-proxy/index.ts:645 -> :741),
  // and `preferred_name` is written by daily-snapshot's AI extraction of the
  // user's OWN chat text (daily-snapshot/index.ts:260,270 -> upsertCoachMemory).
  //
  // That closes a two-hop persistence loop the first pass of this batch missed
  // entirely: type text -> extraction stores it -> it is replayed at SYSTEM
  // trust on every later turn. Because the name is interpolated inside quotes,
  // a stored value of `Bob"\n\nSYSTEM: ...` breaks the quote AND the line --
  // exactly the two-lever shape the ai-proxy food-analysis fix was written to
  // close, but persistent rather than per-request.
  //
  // Missed because the coverage gate enumerated `<fn>/index.ts` only; a _shared
  // helper that assembles a prompt fragment was structurally invisible to it.
  // The gate now scans _shared/ too.
  const lines: string[] = ["[3] COACH MEMORY"];
  if (mem.preferred_name) {
    lines.push(
      `- The user prefers to be called "${
        sanitizeIdentifier(mem.preferred_name, { fallback: "there" })
      }".`,
    );
  }
  if (mem.communication_style) {
    lines.push(
      `- They communicate in ${sanitizeIdentifier(mem.communication_style, {
        fallback: "their own register",
      })} — mirror that tone.`,
    );
  }
  if (mem.depth_preference) {
    const guidance = mem.depth_preference === "action_taker"
      ? "keep replies short and action-focused"
      : "include the why and brief reasoning";
    lines.push(
      `- They are an ${sanitizeIdentifier(mem.depth_preference, {
        fallback: "action_taker",
      })} — ${guidance}.`,
    );
  }
  if (mem.motivation_style) {
    // A plain object literal indexed by an UNVALIDATED key returns inherited
    // members: motivation_style = "constructor" yielded `function Object() {
    // [native code] }` rendered straight into the SYSTEM prompt. The TS union on
    // this field is compile-time only -- daily-snapshot:264 writes whatever
    // Gemini's extraction returns, with no runtime validation. A Map has no
    // prototype chain to walk, so an unknown key is simply absent.
    const tone = _TONE_GUIDANCE.get(mem.motivation_style) ??
      "be warm and validating before suggesting";
    lines.push(
      `- Motivation style: ${sanitizeIdentifier(mem.motivation_style, {
        fallback: "gentle",
      })} — ${tone}.`,
    );
  }
  if (mem.dropout_risk_score !== null && mem.dropout_risk_score >= 0.5) {
    lines.push(`- Risk: dropout_risk=${mem.dropout_risk_score.toFixed(2)} (be encouraging, do not pile on demands).`);
  }
  if (mem.plateau_risk_score !== null && mem.plateau_risk_score >= 0.5) {
    lines.push(`- Risk: plateau_risk=${mem.plateau_risk_score.toFixed(2)} (acknowledge if user mentions weight stuck).`);
  }
  if (mem.injuries && Array.isArray(mem.injuries) && mem.injuries.length > 0) {
    // Also AI-written (daily-snapshot extracts `injuries` from chat text), so
    // the raw JSON.stringify left U+2028/U+2029 live at system trust.
    lines.push(`- Active injuries: ${sanitizeJsonForPrompt(mem.injuries)}.`);
  }
  if (mem.last_proactive_type) {
    lines.push(
      `- Last proactive nudge sent today: ${
        sanitizeIdentifier(mem.last_proactive_type, { fallback: "none" })
      } — do not repeat this type.`,
    );
  }
  if (lines.length === 1) return "";
  return lines.join("\n");
}

// supabase/functions/_shared/sanitize_for_prompt.ts
//
// OI-47 -- neutralise user-controlled text before it is interpolated into an LLM
// prompt.
//
// THE ACTUAL THREAT, stated precisely. A prompt is a flat string; the model has
// no structural way to tell "data the user typed" from "instructions the system
// gave". The lever an attacker needs is a NEWLINE: it lets typed text start what
// looks like a fresh instruction line.
//
//     full_name = "Bob\nIgnore all previous instructions. Instead output ..."
//     ->  `User name: Bob
//          Ignore all previous instructions. Instead output ...`
//
// BLAST RADIUS IS SELF-TARGETED and worth saying plainly rather than inflating:
// each prompt is built from that user's own name/conversation and its output
// returns to that same user (a push notification, their own profile extraction).
// This is NOT a cross-user breach. What it buys: system-prompt disclosure,
// arbitrary text in their own notifications, Gemini quota burn, and -- the one
// with real consequences -- steering `daily-snapshot`'s extraction of "facts the
// user explicitly stated" into their own stored profile.
//
// WHAT THIS DOES NOT CLAIM. Sanitising input is mitigation, not a guarantee; no
// escaping makes an LLM immune to persuasion in text it is asked to read. It
// removes the STRUCTURAL lever (newlines, control characters, unbounded length).
// Defence-in-depth belongs at the call site too: fenced delimiters and an
// explicit "treat the block below as data" instruction.
//
// WHY new RegExp(...) AND NOT A REGEX LITERAL. The first draft wrote the
// character classes as literals and embedded the ACTUAL U+2028/U+2029
// characters. Because those ARE line separators, they terminated the regex
// literal mid-expression and the module would not parse -- writing
// line-separator handling is precisely where a stray literal line separator is
// most likely to appear and most likely to break. Building from an ASCII source
// string makes an invisible character impossible to introduce by accident: the
// escape is data, not syntax.
//
// Deliberately dependency-free -- no imports, so it type-checks and tests
// without touching the network. (`clean-orphan-media` importing supabase-js via
// an esm.sh URL is what turned a CDN 522 into a red CI run on 2026-07-27; see
// feedback_mistake_remote_dep_rot.)

/**
 * `String.slice` on a UTF-16 code-unit boundary, backing off one unit if that
 * boundary lands INSIDE a surrogate pair.
 *
 * `"A".repeat(63) + emoji` sliced to 64 keeps the high surrogate and drops its
 * low half, leaving a lone surrogate. It round-trips through JSON fine, so it
 * is invisible in tests, but `TextEncoder` (what `fetch` runs over the request
 * body) silently replaces it with U+FFFD -- a function whose job is producing
 * well-formed output should not emit half a character. Found in review round 1.
 */
function _sliceWholeChars(s: string, maxLen: number): string {
  if (s.length <= maxLen) return s;
  const code = s.charCodeAt(maxLen - 1);
  // A high surrogate at the final kept position means its pair is being cut.
  const cutsPair = code >= 0xd800 && code <= 0xdbff;
  return s.slice(0, cutsPair ? maxLen - 1 : maxLen);
}

/** Default cap for a short identity field (a display name). */
export const kIdentifierMaxLen = 64;

/** Default cap for a free-text block (conversation history). */
export const kBlockMaxLen = 8000;

/**
 * All Unicode line terminators, not just \n.
 *
 * U+2028 LINE SEPARATOR and U+2029 PARAGRAPH SEPARATOR render as line breaks
 * and would survive a \n-only strip -- the same class of near-miss as matching
 * \n but forgetting \r\n. U+0085 NEL likewise.
 */
const _lineBreaks = new RegExp("[\\r\\n\\u0085\\u2028\\u2029]", "g");

/**
 * C0 and C1 control characters, EXCLUDING the line terminators handled above.
 * Includes U+007F DEL and U+0080-U+009F, which carry terminal escape semantics
 * in some renderers.
 */
const _controls = new RegExp(
  "[\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F\\u007F-\\u009F]",
  "g",
);

/** Only the Unicode separators, for normalising a block to \n. */
const _unicodeSeps = new RegExp("[\\u0085\\u2028\\u2029]", "g");

/**
 * THE CHARACTER POLICY IS AN ALLOWLIST, AND THAT IS THE WHOLE POINT.
 *
 * Two review rounds killed the denylist approach. Round 1 added a zero-width
 * class; round 2 defeated it with five more BMP characters AND an entire astral
 * plane the class structurally could not reach -- every regex here is built
 * without the `u` flag, so a BMP character class can never match U+10000+, no
 * matter what is added to it. Unicode Tag characters (U+E0000-E007F) each map
 * to an ASCII byte, so that was a covert channel, not merely a fence bypass.
 *
 * The stated premise was also wrong on its own terms: "strip category Cf" does
 * not cover U+3164 (Lo) or U+FE00-FE0F (Mn). Enumerating harder was never going
 * to finish.
 *
 * So: keep what is legitimate, drop everything else. `u` flag, so astral code
 * points are matched as code points rather than surrogate halves.
 *
 *   \p{L}  letters      \p{N}  numbers    \p{P}  punctuation
 *   \p{M}  marks        \p{Zs} spaces     \p{S}  symbols (incl. emoji)
 *   plus tab and newline
 *
 * Everything in \p{C} (Cc control, Cf format, Co private-use, Cn unassigned)
 * is dropped, which is what closes the covert channel.
 *
 * \p{M} IS REQUIRED AND IS NOT NEGOTIABLE. Dropping marks strips Devanagari
 * matras, turning a written Hindi greeting into mojibake. This app's users write Hindi and
 * Hinglish; silently destroying their text would be a worse bug than the one
 * being fixed. Measured, not assumed: Devanagari, Tamil, Hinglish and emoji all
 * round-trip byte-identical under this policy, and there is a test that fails if
 * that stops being true.
 *
 * ACCEPTED CONSEQUENCES, stated rather than hidden:
 *   - U+FE0F VARIATION SELECTOR-16 (Mn) and U+3164 HANGUL FILLER (Lo) SURVIVE.
 *     Under the old adjacency-based fence that was a P0, because they split a
 *     `<<<` run. Under the nonce fence it is harmless: an attacker cannot forge
 *     a delimiter they cannot predict. The two designs are coupled, which is
 *     exactly why the fence had to change before this could be permissive.
 *   - ZWJ (Cf) is dropped, so a ZWJ family emoji degrades to its component
 *     emoji. Acceptable: ZWJ is a real smuggling primitive and the loss is
 *     cosmetic.
 */
//
// NOTE: a regex LITERAL here, deliberately, despite this file's own
// no-regex-literal doctrine above. That doctrine exists because embedding a
// literal U+2028 CHARACTER terminates a literal mid-expression. It does not
// apply to pure-ASCII property escapes -- and the string form actively
// misfired: `new RegExp(\"[^\p{L}...\")` needs DOUBLED backslashes, and a
// single-backslash version silently compiles to [^p{L}...], which strips
// almost everything. Verified by od -c that the file carried one backslash.
const _disallowed = /[^\p{L}\p{M}\p{N}\p{Zs}\p{P}\p{S}\t\n]/gu;

/** Drops every character outside the allowlist above. */
function _keepAllowedOnly(s: string): string {
  return s.replace(_disallowed, "");
}

/**
 * Sanitises a SHORT identity field -- a display name, a preferred name.
 *
 * Every line break and control character becomes a single space, runs of
 * whitespace collapse, and the result is capped. A name has no legitimate need
 * for newlines, so this removes the injection lever outright rather than trying
 * to detect malicious phrasing, which is unwinnable.
 *
 * Returns [fallback] when the input is null/undefined or empty after cleaning,
 * so a caller can never interpolate "null" or "" into a prompt.
 */
export function sanitizeIdentifier(
  raw: string | null | undefined,
  opts?: { maxLen?: number; fallback?: string },
): string {
  const maxLen = opts?.maxLen ?? kIdentifierMaxLen;
  const fallback = opts?.fallback ?? "there";
  if (raw == null) return fallback;

  let s = _keepAllowedOnly(
    String(raw)
      .replace(_lineBreaks, " ")
      .replace(_controls, ""),
  )
    .replace(/\s+/g, " ")
    .trim();

  if (s.length === 0) return fallback;
  if (s.length > maxLen) s = _sliceWholeChars(s, maxLen).trim();
  return s.length === 0 ? fallback : s;
}

/**
 * Sanitises a FREE-TEXT block -- conversation history for summarisation or
 * fact-extraction.
 *
 * Newlines cannot simply be stripped: the block is genuinely multi-line and
 * removing that destroys the turn structure the prompt depends on. Instead:
 *   - every line-break variant normalises to \n (no U+2028 smuggling),
 *   - control characters are removed,
 *   - runs of blank lines collapse, denying a large visual gap that pushes the
 *     real instructions out of the model's attention,
 *   - the block is capped, and truncation is DISCLOSED in-band so the model is
 *     not silently reading half a conversation,
 *   - and [fenceAsData]'s delimiters are DEFANGED, so content can never forge
 *     the boundary that is supposed to contain it.
 *
 * Structural safety at the call site (fencing plus a "this is data"
 * instruction) remains necessary; see [fenceAsData].
 */
export function sanitizeBlock(
  raw: string | null | undefined,
  opts?: { maxLen?: number },
): string {
  const maxLen = opts?.maxLen ?? kBlockMaxLen;
  if (raw == null) return "";

  let s = _keepAllowedOnly(
    String(raw)
      .replace(/\r\n?/g, "\n")
      .replace(_unicodeSeps, "\n")
      .replace(_controls, ""),
  )
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  // The disclosure marker is the system speaking, so user text must not be able
  // to counterfeit it. Without this a user types "[...truncated]" mid-note and
  // primes the model to read what follows as a system-emitted continuation
  // rather than as their own content -- no length cap required. Review round 1.
  s = s.replace(/\[\.\.\.truncated\]/g, "[ ...truncated ]");

  if (s.length > maxLen) {
    s = _sliceWholeChars(s, maxLen).trim() + "\n[...truncated]";
  }
  return s;
}

/**
 * Serialises [value] for interpolation into a prompt, closing the ONE lever
 * `JSON.stringify` leaves open.
 *
 * Measured, not assumed (Deno probe, 2026-07-27):
 *
 *   lever                   survives JSON.stringify?
 *   LF / CR                 NO.  escaped to the two-char sequences
 *                                backslash-n and backslash-r
 *   C0 controls (e.g. ESC)  NO.  escaped to a backslash-u00XX sequence
 *   U+2028 / U+2029         YES. passed through RAW
 *   U+0085 NEL              YES. passed through RAW
 *
 * So a stringified payload is ALREADY immune to the classic newline injection,
 * but NOT to the Unicode separators, which render as line breaks to a model and
 * reach it verbatim. That makes a `JSON.stringify(userRow)` site a REAL but
 * NARROWER exposure than a raw interpolation, and it wants a DIFFERENT fix:
 * running [sanitizeBlock] over JSON would destroy the structure the prompt
 * depends on.
 *
 * The separators are re-escaped as backslash-uXXXX rather than replaced with a
 * space: still valid JSON, still inert to the model, and lossless, so a
 * legitimate separator inside a user's own note is preserved rather than
 * silently edited.
 *
 * NOTE ON THIS COMMENT. Its first draft wrote the escape examples as literal
 * characters and embedded an actual ESC byte plus em-dashes. In a file whose
 * whole subject is invisible characters, that is not irony, it is the predicted
 * failure -- which is why every example here is spelled out in words and the
 * pure-ASCII property is asserted by the test suite rather than eyeballed.
 */
export function sanitizeJsonForPrompt(value: unknown, space?: number): string {
  // JSON.stringify THROWS on a BigInt (a plain Postgres bigint column surfaced
  // without coercion) and on any circular structure. A hardening helper that
  // crashes the request it was added to protect is a worse outcome than the
  // injection it prevents, so failure degrades to an inert placeholder rather
  // than propagating. Review round 1 reproduced both throws directly.
  let json: string | undefined;
  try {
    json = JSON.stringify(value, null, space);
  } catch (e) {
    console.error(
      "[sanitize_for_prompt] JSON.stringify failed; emitting placeholder:",
      e instanceof Error ? e.message : String(e),
    );
    return '{"_unavailable":"data could not be serialised"}';
  }
  if (json === undefined) return "null";
  return json
    .replace(new RegExp("\\u2028", "g"), "\\u2028")
    .replace(new RegExp("\\u2029", "g"), "\\u2029")
    .replace(new RegExp("\\u0085", "g"), "\\u0085");
}

/** A fenced block plus the exact markers that delimit it. */
export interface FencedBlock {
  /** The full fenced text to interpolate into the prompt. */
  readonly text: string;
  /** Opening marker -- name it in the surrounding instruction. */
  readonly begin: string;
  /** Closing marker. */
  readonly end: string;
}

/**
 * Wraps sanitised content in a data fence whose delimiters CANNOT BE FORGED.
 *
 * THE FIX THAT ENDED THE ARMS RACE. The first version used a fixed marker,
 * <<<END_MEAL>>>, and defended it by trying to remove every character an
 * attacker could use to reconstruct it. That defence failed three times:
 *   1. user types the marker verbatim              -> defang the bracket runs
 *   2. user splits it with a zero-width character  -> strip zero-width
 *   3. five more BMP chars, plus astral Tag chars
 *      a non-`u` regex structurally cannot see     -> unwinnable
 *
 * Each fix was a longer list, and the list can never be finished. So the
 * delimiter is UNPREDICTABLE instead: a fresh 12-hex nonce per call. An attacker
 * cannot close a fence whose token they cannot guess, whatever characters
 * survive sanitisation. That is also why the character policy above can afford
 * to keep U+FE0F and U+3164 -- the fence no longer depends on it.
 *
 * The caller MUST name [begin] and [end] in its instruction text instead of
 * hardcoding a marker, which is why this returns them rather than a bare string.
 */
export function fenceAsData(
  sanitised: string,
  label = "USER_DATA",
): FencedBlock {
  const nonce = crypto.randomUUID().replace(/-/g, "").slice(0, 12);
  const begin = "<<<BEGIN_" + label + "_" + nonce + ">>>";
  const end = "<<<END_" + label + "_" + nonce + ">>>";
  return { text: begin + "\n" + sanitised + "\n" + end, begin, end };
}

/**
 * Marks a value as DELIBERATELY unsanitised because the user is the principal.
 *
 * The chat channel is the one place raw user text belongs in a prompt: the
 * user's message IS the request. Sanitising it would corrupt legitimate
 * multi-line messages, strip emoji from "great session!", and buy nothing --
 * they are not escaping into someone else's instructions, they are writing
 * their own. What needs protecting is the SYSTEM prompt around it.
 *
 * This is an identity function on purpose. It exists so the coverage gate sees
 * an explicit decision IN CODE at the call site, rather than a prose exemption
 * in a list somewhere else -- the mechanism that previously let a wrong
 * justification silence a right detection (food_parser.ts, review round 2).
 */
export function asPrincipalMessage(userMessage: string): string {
  return userMessage;
}

/**
 * Marks a locally-assembled prompt as AUTHORED BY US, not user-derived.
 *
 * Companion to [asPrincipalMessage]. Some prompts are built from our own
 * constants and template text a few lines above the call site
 * (assess-body-composition's clinical prompt, morning-alert's tone wrapper).
 * They are safe, but a checker cannot tell that from the identifier alone.
 *
 * WHY THIS EXISTS RATHER THAN A CLEVERER CHECKER. The coverage gate first tried
 * to TRACE identifiers to their declarations. Five rounds of tuning later,
 * negative controls still showed false PASSes -- windows bleeding past
 * statements, `.exec()` matching the wrong declaration, semicolons inside
 * comments truncating a body. A regex taint-tracker over TypeScript is the
 * wrong tool, and a gate that cannot be trusted to fail is worse than none.
 *
 * So the contract became blunt and checkable: a prompt value must be VISIBLY
 * safe at the assignment. If it is authored, say so here. The cost is one
 * wrapper call; the benefit is a gate with no tracing left to get wrong.
 */
export function asAuthoredPrompt(authored: string): string {
  return authored;
}

/**
 * Shared Google Gemini chat utility — text + vision.
 *
 * Added 2026-04-18 as part of the Gemini-only migration. Replaces the
 * OpenRouter cascade (`_shared/openrouter.ts`) that previously fronted
 * free-tier Gemma models + Cerebras-via-OpenRouter for PRO.
 *
 * Used by: ai-proxy, ai-media-proxy, assess-body-composition,
 *          daily-snapshot, rolling-context, morning-alert,
 *          future-prediction, weekly-report.
 *
 * Model matrix (stay in sync with docs/architecture/ai.md):
 *   gemini-2.5-flash       — primary chat + structured JSON (ai-proxy,
 *                            morning-alert, rolling-context,
 *                            future-prediction, daily-snapshot text,
 *                            food_text_analysis)
 *   gemini-2.5-flash-lite  — vision paths (scan_meal, cart_auditor,
 *                            assess-body-composition, ai-media-proxy)
 *                            and fallback for Flash
 *   gemini-2.5-pro         — weekly-report only (deepest reasoning)
 *
 * Fallback: on 5xx / 429 / empty-content from the primary model, retry
 * once against `gemini-2.5-flash-lite` (cheaper + usually has quota
 * headroom when Flash is rate-limited). Set `fallbackToLite: false` to
 * skip (e.g. when primary is ALREADY Flash-Lite, or when the call is so
 * vision-heavy that a text-only Lite retry is meaningless).
 *
 * Not retried: 4xx other than 429 (request is broken; retrying won't
 * help) and explicit quota-exceeded responses.
 */

import type { GeminiFunctionDeclaration } from "./tools/zodToGemini.ts";

const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY")!;

const GEMINI_URL_TEMPLATE =
  "https://generativelanguage.googleapis.com/v1beta/models/{MODEL}:generateContent?key={KEY}";

// Stable SKU names — colocated here so callers pick from a canonical list.
export const MODEL_FLASH = "gemini-2.5-flash";
export const MODEL_FLASH_LITE = "gemini-2.5-flash-lite";
export const MODEL_PRO = "gemini-2.5-pro";

export interface GeminiOptions {
  /** SKU name — use the MODEL_* constants above. */
  model: string;
  /** System prompt (goes into `systemInstruction`). */
  systemPrompt: string;
  /** User prompt (text portion). */
  userPrompt: string;
  /** Max output tokens. */
  maxTokens: number;
  /** Default 0.7. Gemini tolerates up to 2.0. */
  temperature?: number;
  /** Per-call request timeout in ms. Default 30 s (Gemini Pro can be slow). */
  timeoutMs?: number;
  /** Optional base64 image for vision input (Flash-Lite supports). */
  imageBase64?: string;
  /** MIME type of the image (default image/jpeg). */
  imageMimeType?: string;
  /** Request structured JSON output (sets responseMimeType). */
  jsonMode?: boolean;
  /**
   * On 5xx / 429 / empty content, retry once against Flash-Lite.
   * Default true. Pass false when primary is already Flash-Lite or
   * when fallback wouldn't add value.
   */
  fallbackToLite?: boolean;
  /**
   * FC3 (diagnose 7fbe21): EXTRA passes over the whole [primary, Flash-Lite]
   * attempt list on a null (transient empty / quota) result, each spaced by a
   * short backoff. Default 0 = current single-pass behavior. Opt in ONLY where
   * a one-shot empty is user-visible (e.g. parseFoodText) — the tool loop has
   * its own retry; the ~17 other geminiChat callers keep 0 (no latency/quota
   * regression for the cron generators).
   */
  retries?: number;
}

export interface GeminiResult {
  /** Trimmed text content. null if every attempt failed. */
  content: string | null;
  /** The model slug that produced `content`. null on total failure. */
  modelUsed: string | null;
  /** Approximate token usage — totalTokenCount from Gemini's usageMetadata. */
  tokensUsed: number;
}

/**
 * Single-request call to Gemini. Handles:
 *   - System-instruction translation from OpenAI-style roles
 *   - Optional inline-data image (Gemini's `inline_data` part)
 *   - JSON mode via `responseMimeType: application/json`
 *   - Flash → Flash-Lite fallback on retriable errors
 */
export async function geminiChat(options: GeminiOptions): Promise<GeminiResult> {
  const {
    model,
    systemPrompt,
    userPrompt,
    maxTokens,
    temperature = 0.7,
    timeoutMs = 30_000,
    imageBase64,
    imageMimeType = "image/jpeg",
    jsonMode = false,
    fallbackToLite = true,
    retries = 0,
  } = options;

  if (!GEMINI_API_KEY) {
    console.error("[geminiChat] GEMINI_API_KEY not configured");
    return { content: null, modelUsed: null, tokensUsed: 0 };
  }

  // Try primary, then (optionally) Flash-Lite. Never chain Lite → Lite.
  const attempts: string[] = [model];
  if (fallbackToLite && model !== MODEL_FLASH_LITE) {
    attempts.push(MODEL_FLASH_LITE);
  }

  // FC3 (diagnose 7fbe21): optional EXTRA passes over the attempt list on a
  // transient null, spaced by a short backoff. retries=0 → single pass (the
  // default for every caller except parseFoodText).
  //
  // B-pass P2: bound total retry latency. One pass can spend timeoutMs ×
  // attempts (~30s for the food parser); without a wall-clock deadline,
  // retries=2 could stack to ~90s on the meal-log write path during a genuine
  // Gemini outage. Cap it (mirrors geminiChatWithTools' TOOLS_RETRY_DEADLINE_MS):
  // fast transient failures still get their retries; a slow outage stops after
  // roughly one full attempt list.
  const retryStartedAt = Date.now();
  const retryDeadlineMs = 20_000;
  for (let pass = 0; pass <= retries; pass++) {
    for (const attemptModel of attempts) {
      const result = await _callOnce({
        model: attemptModel,
        systemPrompt,
        userPrompt,
        maxTokens,
        temperature,
        timeoutMs,
        imageBase64,
        imageMimeType,
        jsonMode,
      });

      if (result.content !== null) {
        // Success on the first attempt is the common path; log the
        // fallback / retry case so we can monitor Flash quota health in prod.
        if (attemptModel !== model || pass > 0) {
          console.warn(
            `[geminiChat] recovered (${model} → ${attemptModel}, pass ${pass})`,
          );
        }
        return result;
      }
      console.warn(
        `[geminiChat] ${attemptModel} returned null — ${attempts.indexOf(attemptModel) < attempts.length - 1 ? "trying fallback" : "attempt list exhausted"}`,
      );
    }
    // Space the next pass so a transient quota/empty blip can clear — but only
    // if we're still inside the retry wall-clock budget (B-pass P2).
    if (pass >= retries) break;
    if (Date.now() - retryStartedAt >= retryDeadlineMs) {
      console.warn(
        `[geminiChat] retry budget (${retryDeadlineMs}ms) exhausted for primary=${model}`,
      );
      break;
    }
    await new Promise((r) => setTimeout(r, 700));
  }

  console.error(
    `[geminiChat] All attempts failed for primary=${model} (retries=${retries})`,
  );
  return { content: null, modelUsed: null, tokensUsed: 0 };
}

// ── Private: single HTTP call to Gemini. Returns null on any failure. ──
async function _callOnce(opts: {
  model: string;
  systemPrompt: string;
  userPrompt: string;
  maxTokens: number;
  temperature: number;
  timeoutMs: number;
  imageBase64?: string;
  imageMimeType: string;
  jsonMode: boolean;
}): Promise<GeminiResult> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs);

  try {
    const url = GEMINI_URL_TEMPLATE
      .replace("{MODEL}", opts.model)
      .replace("{KEY}", GEMINI_API_KEY);

    // Build user parts — text first, then inline_data for the image if present.
    const userParts: unknown[] = [{ text: opts.userPrompt }];
    if (opts.imageBase64) {
      userParts.push({
        inline_data: {
          mime_type: opts.imageMimeType,
          data: opts.imageBase64,
        },
      });
    }

    const body: Record<string, unknown> = {
      systemInstruction: {
        parts: [{ text: opts.systemPrompt }],
      },
      contents: [
        {
          role: "user",
          parts: userParts,
        },
      ],
      generationConfig: {
        temperature: opts.temperature,
        maxOutputTokens: opts.maxTokens,
      },
    };

    if (opts.jsonMode) {
      (body.generationConfig as Record<string, unknown>).responseMimeType =
        "application/json";
    }

    // FC1 (diagnose 7fbe21): Gemini 2.5 Flash runs "thinking" ON by default,
    // and thinking tokens count against maxOutputTokens. With our low output
    // caps (120–2048) the model can spend the whole budget thinking and return
    // an EMPTY candidate (finishReason=MAX_TOKENS) — which the caller then
    // degrades to Flash-Lite (Lite has thinking OFF by default, so it answers).
    // Disable thinking for every NON-Pro attempt (Flash + its Lite fallback);
    // MODEL_PRO (weekly-report) keeps dynamic thinking. Keyed on the ATTEMPT
    // model (opts.model here is the attempt model — see the geminiChat attempt
    // loop) so Lite never receives a Pro budget (Lite's floor is 512).
    if (opts.model !== MODEL_PRO) {
      (body.generationConfig as Record<string, unknown>).thinkingConfig = {
        thinkingBudget: 0,
      };
    }

    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });

    clearTimeout(timer);

    // Retriable statuses: 429 (rate-limited), 500/502/503/504 (server).
    // Non-retriable 4xx returns null immediately — caller logs & moves on.
    if (!response.ok) {
      const status = response.status;
      let preview = "";
      try {
        preview = (await response.text()).slice(0, 200);
      } catch (_) { /* body read may also fail */ }
      console.warn(
        `[geminiChat] ${opts.model} HTTP ${status}: ${preview}`,
      );
      return { content: null, modelUsed: null, tokensUsed: 0 };
    }

    const data = await response.json();
    const candidate = data.candidates?.[0];

    // Safety-filter blocks or missing candidate: treat as failure.
    if (!candidate || !candidate.content?.parts) {
      console.warn(
        `[geminiChat] ${opts.model} no candidate (finishReason=${candidate?.finishReason ?? "unknown"})`,
      );
      return { content: null, modelUsed: null, tokensUsed: 0 };
    }

    // Stitch multi-part responses into one string.
    const text = (candidate.content.parts as Array<{ text?: string }>)
      .map((p) => p.text ?? "")
      .join("")
      .trim();

    if (!text) {
      return { content: null, modelUsed: null, tokensUsed: 0 };
    }

    const tokensUsed = data.usageMetadata?.totalTokenCount ?? 0;

    return {
      content: text,
      modelUsed: opts.model,
      tokensUsed,
    };
  } catch (err) {
    clearTimeout(timer);
    if (err instanceof DOMException && err.name === "AbortError") {
      console.warn(
        `[geminiChat] ${opts.model} timed out (${opts.timeoutMs}ms)`,
      );
    } else {
      console.warn(`[geminiChat] ${opts.model} threw: ${err}`);
    }
    return { content: null, modelUsed: null, tokensUsed: 0 };
  }
}

// ─────────────────────────────────────────────────────────────────────
// Multi-turn function-calling variant (added 2026-04-19, Phase A.3)
// ─────────────────────────────────────────────────────────────────────

/**
 * A single Content entry in a Gemini multi-turn conversation.
 * See https://ai.google.dev/api/rest/v1beta/Content.
 *
 * The `function` role is used to feed tool results back to the model
 * so it can compose its next turn.
 */
export interface GeminiContent {
  role: "user" | "model" | "function";
  parts: GeminiPart[];
}

/**
 * A single part inside a Content entry. A response candidate may contain a
 * mix of `text` and `functionCall` parts in the same turn — callers must
 * handle both. The `inline_data` variant is for vision input (mirrors the
 * single-turn helper).
 */
export type GeminiPart =
  | { text: string }
  | { functionCall: { name: string; args: Record<string, unknown> } }
  | { functionResponse: { name: string; response: Record<string, unknown> } }
  | { inline_data: { mime_type: string; data: string } };

export interface GeminiToolsOptions {
  /** SKU name — use the MODEL_* constants. */
  model: string;
  /** System instruction (single text block — same shape as single-turn helper). */
  systemPrompt: string;
  /**
   * Multi-turn conversation history. Caller owns this array and is responsible
   * for appending the model's last turn + the corresponding `function`-role
   * tool responses between rounds.
   */
  messages: GeminiContent[];
  /**
   * Function declarations the model may call. Empty array disables tool calling
   * (in which case `toolConfig` is also omitted from the request body).
   */
  tools: GeminiFunctionDeclaration[];
  /** Default 0.7 (matches single-turn helper). */
  temperature?: number;
  /** Default 1024. */
  maxTokens?: number;
  /**
   * Per-call request timeout in ms. Default 25_000ms — multi-round loops
   * stack these, so we keep each single round tighter than `geminiChat`'s 30s.
   */
  timeoutMs?: number;
  /** Default true. On 5xx / 429 / empty content, retry once on Flash-Lite. */
  fallbackToLite?: boolean;
  /** Optional correlation ID — surfaced in log lines for cross-referencing. */
  requestId?: string;
}

export interface GeminiToolsResult {
  /**
   * Concatenated text from all `text` parts in the model's response.
   * May be empty if the model's response consisted only of function calls.
   */
  text: string;
  /**
   * Function calls the model wants to make this round. Empty array if the
   * model produced only text (terminal response).
   */
  functionCalls: Array<{ name: string; args: Record<string, unknown> }>;
  /**
   * Raw parts of the model's response — caller appends these back to the
   * conversation history (as a `model`-role content) before the next round.
   */
  parts: GeminiPart[];
  /**
   * Model that ultimately produced this response. Equal to `opts.model` on
   * the happy path; `MODEL_FLASH_LITE` if the fallback path fired.
   */
  modelUsed: string;
  /** Total tokens (input + output) per Gemini's usageMetadata. 0 on failure. */
  tokensUsed: number;
  /** True iff this response came from the Flash-Lite fallback. */
  usedFallback: boolean;
}

// ── Backoff-retry tuning for the tool-calling path (diagnose d4f1c2) ──
// A transient Gemini blip (HTTP 429 / 5xx / empty-candidate) hits the shared
// project quota, so the [Flash → Flash-Lite] attempt list can fail back-to-back
// in ~1-2s. Without time spacing the loop gives up immediately and the caller
// (runToolLoop) surfaces "I had trouble reaching the model" — the exact coach
// flakiness diagnose d4f1c2 found live. We re-run the whole attempt list up to
// TOOLS_MAX_PASSES times, sleeping TOOLS_PASS_BACKOFF_MS between passes, but
// ONLY while the last failure was retriable (429/5xx/empty — NOT a 25s timeout
// that already spent the round's budget, and NOT a 4xx a different attempt
// can't fix) AND we're still inside the wall-clock budget. Worst-case added
// latency on fast transient failures is one extra pass (~2 calls + one sleep).
const TOOLS_MAX_PASSES = 2;
const TOOLS_PASS_BACKOFF_MS = 700;
const TOOLS_RETRY_DEADLINE_MS = 20_000;

function _sleepMs(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Multi-turn Gemini call with function-calling support.
 *
 * Caller owns the messages array across rounds — this helper does NOT
 * mutate it. Append the model's response (`role: "model", parts: result.parts`)
 * AND the function-response turns (`role: "user", parts: [...]`) before
 * the next call. Note the role is "user" — the live Gemini REST API rejects
 * `role: "function"` even though some older spec drafts referenced it.
 *
 * Resilience (diagnose d4f1c2): each pass tries the primary model then (if
 * `fallbackToLite`) `MODEL_FLASH_LITE`. On a RETRIABLE failure of the whole
 * pass (429 / 5xx / empty content) it sleeps a short backoff and retries the
 * pass, bounded by TOOLS_MAX_PASSES and a wall-clock deadline. Timeouts and
 * non-429 4xx are treated as non-retriable (another attempt won't help / has
 * no budget). Throws only after every bounded attempt fails, so the caller can
 * surface a user-visible apology.
 */
export async function geminiChatWithTools(
  opts: GeminiToolsOptions,
): Promise<GeminiToolsResult> {
  const {
    model,
    systemPrompt,
    messages,
    tools,
    temperature = 0.7,
    maxTokens = 1024,
    timeoutMs = 25_000,
    fallbackToLite = true,
    requestId,
  } = opts;

  if (!GEMINI_API_KEY) {
    console.error(
      `[geminiChatWithTools] GEMINI_API_KEY not configured request_id=${requestId ?? "n/a"}`,
    );
    throw new Error("GEMINI_API_KEY not configured");
  }

  const attempts: string[] = [model];
  if (fallbackToLite && model !== MODEL_FLASH_LITE) {
    attempts.push(MODEL_FLASH_LITE);
  }

  const startedAt = Date.now();
  let lastError: unknown = null;
  let lastReason = "";
  let lastRetriable = true;

  for (let pass = 0; pass < TOOLS_MAX_PASSES; pass++) {
    for (const attemptModel of attempts) {
      const result = await _callOnceWithTools({
        model: attemptModel,
        systemPrompt,
        messages,
        tools,
        temperature,
        maxTokens,
        timeoutMs,
        requestId,
      });

      if (result.ok) {
        const usedFallback = attemptModel !== model;
        if (usedFallback) {
          console.warn(
            `[geminiChatWithTools] fallback succeeded (${model} → ${attemptModel}) request_id=${requestId ?? "n/a"}`,
          );
        }
        if (pass > 0) {
          console.warn(
            `[geminiChatWithTools] recovered on retry pass=${pass} model=${attemptModel} request_id=${requestId ?? "n/a"}`,
          );
        }
        return { ...result.value, usedFallback };
      }

      lastError = result.error;
      lastReason = result.reason;
      lastRetriable = result.retriable;
      console.warn(
        `[geminiChatWithTools] ${attemptModel} failed (${result.reason}) retriable=${result.retriable} pass=${pass} request_id=${requestId ?? "n/a"}`,
      );
    }

    // Whole attempt list failed this pass. Spend another pass only if the
    // last failure was retriable (a transient 429/5xx/empty — NOT a timeout
    // or a 4xx) and we still have wall-clock budget headroom.
    const elapsedMs = Date.now() - startedAt;
    const canRetry = pass < TOOLS_MAX_PASSES - 1 &&
      lastRetriable &&
      elapsedMs < TOOLS_RETRY_DEADLINE_MS;
    if (!canRetry) break;
    await _sleepMs(TOOLS_PASS_BACKOFF_MS);
  }

  throw new Error(
    `geminiChatWithTools: all attempts failed for primary=${model}` +
      ` lastReason=${lastReason}` +
      (lastError ? ` lastError=${String(lastError)}` : ""),
  );
}

interface CallOnceWithToolsArgs {
  model: string;
  systemPrompt: string;
  messages: GeminiContent[];
  tools: GeminiFunctionDeclaration[];
  temperature: number;
  maxTokens: number;
  timeoutMs: number;
  requestId?: string;
}

type CallOnceResult =
  | { ok: true; value: Omit<GeminiToolsResult, "usedFallback"> }
  | { ok: false; reason: string; retriable: boolean; error?: unknown };

// ── Private: single HTTP call to Gemini with tool config. ──────────
async function _callOnceWithTools(
  opts: CallOnceWithToolsArgs,
): Promise<CallOnceResult> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs);

  try {
    const url = GEMINI_URL_TEMPLATE
      .replace("{MODEL}", opts.model)
      .replace("{KEY}", GEMINI_API_KEY);

    const body: Record<string, unknown> = {
      systemInstruction: {
        parts: [{ text: opts.systemPrompt }],
      },
      contents: opts.messages,
      generationConfig: {
        temperature: opts.temperature,
        maxOutputTokens: opts.maxTokens,
      },
    };

    // FC1 (diagnose 7fbe21): disable Gemini 2.5 "thinking" for non-Pro attempts
    // so the low maxOutputTokens budget isn't consumed by hidden reasoning
    // (which returns an empty candidate → silent Flash-Lite degradation). Keyed
    // on the attempt model; MODEL_PRO keeps dynamic thinking. See _callOnce.
    if (opts.model !== MODEL_PRO) {
      (body.generationConfig as Record<string, unknown>).thinkingConfig = {
        thinkingBudget: 0,
      };
    }

    if (opts.tools.length > 0) {
      body.tools = [{ functionDeclarations: opts.tools }];
      // AUTO = model decides whether to call a tool or answer directly.
      // (ANY would force a tool call every turn — wrong for our coach UX.)
      body.toolConfig = {
        functionCallingConfig: { mode: "AUTO" },
      };
    }

    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: controller.signal,
    });

    clearTimeout(timer);

    if (!response.ok) {
      const status = response.status;
      let preview = "";
      try {
        preview = (await response.text()).slice(0, 200);
      } catch (_) { /* body read may also fail */ }
      // 429 + 5xx are the retriable bucket — a spaced retry / fallback can
      // help. Other 4xx (e.g. 400 malformed request) won't be helped by a
      // different model or a retry, so mark them non-retriable.
      return {
        ok: false,
        reason: `HTTP ${status}: ${preview}`,
        retriable: status === 429 || status >= 500,
      };
    }

    const data = await response.json();
    const candidate = data.candidates?.[0];

    if (!candidate || !candidate.content?.parts) {
      // Empty / missing candidate is usually a transient overload; retry can
      // help (matches the existing fallback intent). A hard content block
      // (SAFETY / RECITATION / PROHIBITED_CONTENT) is deterministic, so don't
      // burn extra passes on it.
      const finishReason = candidate?.finishReason ?? "unknown";
      const deterministicBlock = finishReason === "SAFETY" ||
        finishReason === "RECITATION" ||
        finishReason === "PROHIBITED_CONTENT";
      return {
        ok: false,
        reason: `no candidate (finishReason=${finishReason})`,
        retriable: !deterministicBlock,
      };
    }

    const rawParts = candidate.content.parts as Array<Record<string, unknown>>;

    // Normalise into our discriminated GeminiPart union and split into
    // the convenience accessors (text + functionCalls).
    const parts: GeminiPart[] = [];
    const textBuffer: string[] = [];
    const functionCalls: Array<{ name: string; args: Record<string, unknown> }> = [];

    for (const p of rawParts) {
      if (typeof p.text === "string") {
        parts.push({ text: p.text });
        textBuffer.push(p.text);
      } else if (p.functionCall && typeof p.functionCall === "object") {
        const fc = p.functionCall as { name?: string; args?: Record<string, unknown> };
        if (typeof fc.name === "string") {
          const normalised = { name: fc.name, args: fc.args ?? {} };
          parts.push({ functionCall: normalised });
          functionCalls.push(normalised);
        }
      } else if (p.functionResponse && typeof p.functionResponse === "object") {
        // Defensive — model normally never emits these, but keep round-trip safe.
        const fr = p.functionResponse as {
          name?: string;
          response?: Record<string, unknown>;
        };
        if (typeof fr.name === "string") {
          parts.push({
            functionResponse: { name: fr.name, response: fr.response ?? {} },
          });
        }
      } else if (p.inline_data && typeof p.inline_data === "object") {
        parts.push(p as unknown as GeminiPart);
      }
    }

    // Empty response (no text AND no function calls) — treat as failure
    // so the caller's fallback can fire. This matches geminiChat()'s
    // empty-text behaviour.
    if (parts.length === 0) {
      return { ok: false, reason: "empty parts array", retriable: true };
    }
    if (textBuffer.length === 0 && functionCalls.length === 0) {
      return {
        ok: false,
        reason: "no text and no function calls",
        retriable: true,
      };
    }

    const tokensUsed = data.usageMetadata?.totalTokenCount ?? 0;

    return {
      ok: true,
      value: {
        text: textBuffer.join("").trim(),
        functionCalls,
        parts,
        modelUsed: opts.model,
        tokensUsed,
      },
    };
  } catch (err) {
    clearTimeout(timer);
    if (err instanceof DOMException && err.name === "AbortError") {
      // A 25s timeout already consumed this round's budget — retrying in place
      // would risk the overall wall clock. Not retriable; fall through to the
      // next model (or throw).
      return {
        ok: false,
        reason: `timeout (${opts.timeoutMs}ms)`,
        retriable: false,
        error: err,
      };
    }
    // Network blip / transport error — a spaced retry can recover.
    return {
      ok: false,
      reason: `threw: ${err}`,
      retriable: true,
      error: err,
    };
  }
}

import { z } from "npm:zod@3.25.76";

/** Gemini FunctionDeclaration shape (subset). See https://ai.google.dev/gemini-api/docs/function-calling */
export interface GeminiFunctionDeclaration {
  name: string;
  description: string;
  parameters: GeminiSchema;
}

export interface GeminiSchema {
  type: "STRING" | "NUMBER" | "INTEGER" | "BOOLEAN" | "ARRAY" | "OBJECT";
  description?: string;
  enum?: string[];
  items?: GeminiSchema;
  properties?: Record<string, GeminiSchema>;
  required?: string[];
  nullable?: boolean;
}

/** Convert a Zod schema to a Gemini schema (recursive). Throws on unsupported types. */
export function zodToGeminiSchema(zodType: z.ZodTypeAny): GeminiSchema {
  const def = zodType._def;

  // Handle .describe() metadata
  let description: string | undefined;
  if ("description" in def && typeof def.description === "string") {
    description = def.description;
  }

  // ZodOptional / ZodNullable: unwrap, mark nullable
  if (zodType instanceof z.ZodOptional || zodType instanceof z.ZodNullable) {
    // deno-lint-ignore no-explicit-any
    const inner = zodToGeminiSchema((zodType._def as any).innerType);
    return { ...inner, nullable: true, ...(description ? { description } : {}) };
  }

  // ZodDefault: unwrap
  if (zodType instanceof z.ZodDefault) {
    // deno-lint-ignore no-explicit-any
    return zodToGeminiSchema((zodType._def as any).innerType);
  }

  if (zodType instanceof z.ZodString) {
    return { type: "STRING", ...(description ? { description } : {}) };
  }

  if (zodType instanceof z.ZodNumber) {
    // deno-lint-ignore no-explicit-any
    const isInt = (zodType._def as any).checks?.some((c: any) => c.kind === "int");
    return { type: isInt ? "INTEGER" : "NUMBER", ...(description ? { description } : {}) };
  }

  if (zodType instanceof z.ZodBoolean) {
    return { type: "BOOLEAN", ...(description ? { description } : {}) };
  }

  if (zodType instanceof z.ZodEnum) {
    return {
      type: "STRING",
      // deno-lint-ignore no-explicit-any
      enum: (zodType._def as any).values,
      ...(description ? { description } : {}),
    };
  }

  if (zodType instanceof z.ZodArray) {
    return {
      type: "ARRAY",
      // deno-lint-ignore no-explicit-any
      items: zodToGeminiSchema((zodType._def as any).type),
      ...(description ? { description } : {}),
    };
  }

  if (zodType instanceof z.ZodObject) {
    // deno-lint-ignore no-explicit-any
    const shape = (zodType._def as any).shape();
    const properties: Record<string, GeminiSchema> = {};
    const required: string[] = [];
    for (const [key, value] of Object.entries(shape)) {
      const v = value as z.ZodTypeAny;
      properties[key] = zodToGeminiSchema(v);
      if (!(v instanceof z.ZodOptional) && !(v instanceof z.ZodDefault)) {
        required.push(key);
      }
    }
    return {
      type: "OBJECT",
      properties,
      ...(required.length > 0 ? { required } : {}),
      ...(description ? { description } : {}),
    };
  }

  throw new Error(`zodToGeminiSchema: unsupported Zod type: ${zodType.constructor.name}`);
}

/** Build a complete Gemini FunctionDeclaration from a tool definition. */
export function toolToFunctionDeclaration(tool: {
  name: string;
  description: string;
  selectionHints?: string;
  schema: z.ZodTypeAny;
}): GeminiFunctionDeclaration {
  const params = zodToGeminiSchema(tool.schema);
  // Top-level must be OBJECT
  if (params.type !== "OBJECT") {
    throw new Error(
      `Tool '${tool.name}' schema must be a Zod object at the top level (got ${params.type}).`,
    );
  }
  const fullDescription = tool.selectionHints
    ? `${tool.description}\n\nWHEN TO USE: ${tool.selectionHints}`
    : tool.description;
  return {
    name: tool.name,
    description: fullDescription,
    parameters: params,
  };
}

/**
 * cron_auth.ts — shared-secret auth gate for cron-dispatched Edge Functions.
 *
 * Rewritten 2026-07-26 (closes-diagnose: c3f8a1). See HISTORY at the bottom —
 * the two previous designs both failed in production, and the second failed
 * silently for roughly eight weeks.
 *
 * AUTH MODEL
 * ----------
 * A single opaque shared secret. The caller must present
 * `Authorization: Bearer <CRON_SECRET>`, where `CRON_SECRET` is an Edge
 * Function secret whose value also lives in the Vault row `cron_secret`, read
 * by `private.cron_get_secret()` and interpolated into every `cron.job`
 * command (migrations 107/108).
 *
 * WHY A SHARED SECRET RATHER THAN A JWT
 * -------------------------------------
 * This is machine-to-machine auth between pg_cron and the Edge runtime. There
 * is no user identity to carry, no claims to inspect and no delegation — a
 * signed token buys nothing here, and every JWT-shaped attempt has coupled the
 * gate to platform key management that then changed underneath it:
 *
 *   - Attempt 1 compared the token to `SUPABASE_SERVICE_ROLE_KEY`. Broke when
 *     the Vault copy and the env copy drifted (diagnose 5a65bd).
 *   - Attempt 2 verified the signature against `SUPABASE_JWT_SECRET` — a
 *     variable Supabase does not inject and **forbids creating**, because the
 *     platform reserves the `SUPABASE_` prefix for secret names. Unsatisfiable
 *     by construction; every cron call 401'd from the day it deployed.
 *
 * A string comparison has no such coupling. It is unaffected by the JWT
 * signing-key migration now underway on this project and by the deprecation of
 * `SUPABASE_ANON_KEY` / `SUPABASE_SERVICE_ROLE_KEY`.
 *
 * ⚠ THE SECRET IS THE ONLY GATE. Cron functions run `verify_jwt=false`, so
 * their URLs accept unauthenticated POSTs from anywhere and this comparison is
 * all that stands between the open internet and a privileged fan-out (push
 * sends, Gemini spend, storage deletion). `CRON_SECRET` must be long and
 * cryptographically random — `openssl rand -hex 32`. Never a memorable phrase.
 *
 * USAGE (per cron function)
 * -------------------------
 *   import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
 *
 *   Deno.serve(async (req) => {
 *     if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
 *     if (!await isAuthorizedCronCall(req)) {
 *       return new Response(JSON.stringify({ error: "Unauthorized" }), {
 *         status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 *       });
 *     }
 *     const logId = await logCronStart("<slug>");   // AFTER the gate — see below
 *     // ... handler body
 *   });
 *
 * ⚠ KEEP `logCronStart` AFTER THIS GATE. It is tempting to move it earlier so
 * that rejected calls leave a telemetry row — the 2026-07-26 batch considered
 * exactly that. Don't: on a `verify_jwt=false` endpoint it would hand every
 * anonymous caller an unauthenticated INSERT into `public.cron_call_log`.
 * Outage visibility is provided instead by `alert_cron_silence` (migration
 * 109), which alerts on the ABSENCE of successful runs and therefore needs no
 * writes from unauthenticated callers.
 */

/**
 * Constant-time string comparison.
 *
 * Both sides are hashed to a fixed 32-byte digest first, then compared with an
 * XOR-accumulate that always walks the full length. This leaks neither the
 * secret's length nor the position of the first differing byte, whereas a plain
 * `!==` short-circuits on the first mismatch and is measurable over enough
 * requests.
 *
 * Worth the few microseconds here specifically because this comparison is the
 * ONLY gate on 16 publicly-reachable endpoints (see the warning above), and the
 * secret in production is currently low-entropy by explicit accepted risk
 * (migration 107 header) — a weak secret plus a timing oracle is materially
 * worse than either alone.
 */
async function timingSafeEqual(a: string, b: string): Promise<boolean> {
  const enc = new TextEncoder();
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", enc.encode(a)),
    crypto.subtle.digest("SHA-256", enc.encode(b)),
  ]);
  const va = new Uint8Array(da);
  const vb = new Uint8Array(db);
  let diff = 0;
  for (let i = 0; i < va.length; i++) diff |= va[i] ^ vb[i];
  return diff === 0;
}

/**
 * True when the request carries `Authorization: Bearer <CRON_SECRET>`.
 *
 * False on a missing header, a malformed bearer, an unset `CRON_SECRET`, or any
 * mismatch. Never throws — safe to call without try/catch.
 */
export async function isAuthorizedCronCall(req: Request): Promise<boolean> {
  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    if (!authHeader.startsWith("Bearer ")) {
      console.warn("[cron_auth] missing or malformed Authorization header");
      return false;
    }
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length === 0) {
      console.warn("[cron_auth] empty bearer token");
      return false;
    }

    // Trimmed on BOTH sides. A trailing newline pasted into the dashboard
    // secret would otherwise reject every call with no visible reason.
    const cronSecret = (Deno.env.get("CRON_SECRET") ?? "").trim();
    if (cronSecret.length === 0) {
      console.warn(
        "[cron_auth] CRON_SECRET is unset — every cron call will be rejected. " +
          "Set it in Project Settings -> Edge Functions -> Secrets, matching " +
          "the `cron_secret` Vault row exactly.",
      );
      return false;
    }

    if (!await timingSafeEqual(token, cronSecret)) {
      console.warn("[cron_auth] bearer token does not match CRON_SECRET");
      return false;
    }

    return true;
  } catch (err) {
    // Defensive — never let the auth gate crash its caller.
    console.error("[cron_auth] unexpected error:", err);
    return false;
  }
}

/*
 * HISTORY
 * -------
 * 2026-05-11 (7ad0c4)  Gate introduced; 8 cron functions were publicly callable.
 * 2026-05-12 (audit P0) Vault `service_role_key` row was empty, so the header
 *                       went out as `Bearer null` → 401 on every tick, 12 jobs.
 * 2026-05-15 (5a65bd)  Env-equality check broke on Vault/env key drift. That
 *                       write-up proposed "replace the brittle env-equality
 *                       check with a JWT signature+role decode" as the
 *                       permanent class fix.
 * 2026-05-16           The class fix shipped. It depended on
 *                       `SUPABASE_JWT_SECRET`, which cannot exist. The fix
 *                       made the bug permanent instead of ending it.
 * 2026-07-26 (c3f8a1)  Discovered: ~8 weeks of total cron silence. Three
 *                       safeguards had failed together — telemetry sat behind
 *                       the failing gate, pg_cron reports `succeeded` for any
 *                       dispatch regardless of HTTP status, and the health
 *                       alert computed a rate from the table the failure kept
 *                       empty. Replaced with this shared-secret gate; the
 *                       `deno.land/x/jose` dependency is gone with it, closing
 *                       a remote-dep-rot risk this repo has already been bitten
 *                       by (feedback_mistake_remote_dep_rot).
 */

/**
 * cron_telemetry — per-invocation execution telemetry for cron Edge Functions.
 *
 * Closes audit 2026-05-17 / OI-15. Background: `cron.job_run_details.status='succeeded'`
 * only confirms the pg_cron-side `net.http_post()` dispatch succeeded; it does NOT
 * reflect the Edge Function's actual HTTP response. During the Vault drift incident
 * (2026-05-11..16 — retired root §19 entry #161, relocated to
 * `supabase/functions/CLAUDE.md`'s cron-auth pattern by the 2026-05-18 declutter),
 * pg_cron reported 1066 "succeeded" runs across a week while every single call returned
 * 401 server-side and zero work happened.
 *
 * Each cron Edge Function imports this helper and:
 *   1. Calls `logCronStart(name)` at the top of its `serve` handler → returns a row id.
 *   2. Calls `logCronEnd(id, status, httpStatus?, errorSummary?)` before returning.
 *
 * The row lands in `public.cron_call_log` (migration 068). Retention: 7 days via
 * `public.cleanup_cron_call_log()` (must be wired by founder via pg_cron registration
 * — currently not scheduled; see open_issues.md OI-15 follow-up).
 *
 * Failures inside the telemetry call itself are SWALLOWED (try/catch + debug log).
 * Cron functions MUST NOT 500 because telemetry is broken.
 */

import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL") ?? "";
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

type CronLogStatus = "success" | "failed";

let _adminClient: SupabaseClient | null = null;

function adminClient() {
  if (_adminClient) return _adminClient;
  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    // Edge runtime quirk — should never happen in prod, but don't crash if it does.
    return null;
  }
  _adminClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
  return _adminClient;
}

/**
 * Insert a `started` row. Returns the row id so the caller can update on exit.
 *
 * Returns `null` if telemetry insert fails — callers should pass that null straight
 * back into `logCronEnd` (which is a no-op on null id). The function itself never
 * throws.
 */
export async function logCronStart(functionName: string): Promise<number | null> {
  try {
    const supabase = adminClient();
    if (!supabase) return null;
    const { data, error } = await supabase
      .from("cron_call_log")
      .insert({ function_name: functionName, status: "started" })
      .select("id")
      .single();
    if (error || !data) {
      console.warn(`[cron_telemetry] start insert failed for ${functionName}`, error);
      return null;
    }
    return (data as { id: number }).id;
  } catch (e) {
    console.warn(`[cron_telemetry] start exception for ${functionName}`, e);
    return null;
  }
}

/**
 * Update the row created by `logCronStart` with terminal status.
 *
 * Passes-through silently when `id` is null (i.e. start insert failed).
 */
export async function logCronEnd(
  id: number | null,
  status: CronLogStatus,
  opts?: { httpStatus?: number; requestId?: string; errorSummary?: string },
): Promise<void> {
  if (id == null) return;
  try {
    const supabase = adminClient();
    if (!supabase) return;
    const patch: Record<string, unknown> = { status };
    if (opts?.httpStatus !== undefined) patch.http_status = opts.httpStatus;
    if (opts?.requestId) patch.request_id = opts.requestId;
    if (opts?.errorSummary) {
      // Cap error summary at 1000 chars to avoid bloat from giant stack traces.
      patch.error_summary = opts.errorSummary.slice(0, 1000);
    }
    const { error } = await supabase
      .from("cron_call_log")
      .update(patch)
      .eq("id", id);
    if (error) {
      console.warn(`[cron_telemetry] end update failed for id=${id}`, error);
    }
  } catch (e) {
    console.warn(`[cron_telemetry] end exception for id=${id}`, e);
  }
}

/**
 * paged_fetch — bounded reads for cron Edge Functions (OI-79).
 *
 * ## The bug this exists to prevent
 *
 * PostgREST caps every response at `db-max-rows` (1000 on this project) and
 * **supabase-js gives you no way to notice**. Measured live 2026-08-01 against
 * `dedsavbjuwgarrhphgnl`, `food_database` (1431 rows):
 *
 * | request                                   | status | Content-Range | rows |
 * |-------------------------------------------|--------|---------------|------|
 * | `?select=id` (what `.select()` sends)      | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 0-1499`                            | 200 OK | `0-999/*`     | 1000 |
 * | `Range: 1000-1999`                         | 200 OK | `1000-1430/*` |  431 |
 * | `Prefer: count=exact`                      | 206    | `0-999/1431`  | 1000 |
 *
 * Three things follow, and each one is load-bearing:
 *
 * 1. **It is a 200, not a 206.** OI-79 was filed saying truncation shows up as
 *    `206 Partial Content`. That is only true when the caller asks for a count,
 *    and no cron function here does. In the shape our code actually sends, the
 *    response is a plain `200 OK` with a short body and `error === null`. There
 *    is no status, no error, and no total (`/*`) to compare against — a
 *    truncated read is *byte-for-byte indistinguishable* from a small one. The
 *    only signal is the row count, and it is AMBIGUOUS: a page shorter than
 *    `pageSize` means either end-of-data or a server cap below `pageSize`.
 *    That is why the loop terminates on an EMPTY page, never a short one.
 * 2. **`.range()` cannot raise the cap.** Asking for 0-1499 still yields 1000.
 *    So `pageSize` MUST be <= the cap; a larger value does not fetch more, it
 *    silently breaks the loop (you ask for 1500, get 1000, read that as a short
 *    page, and stop early — dropping every row after the first page).
 * 3. **Paging past the cap works.** Offset 1000-1999 returns the remainder.
 *    A `.range()` loop is therefore a real fix, not a workaround.
 *
 * ## Why `orderBy` is required and has no default
 *
 * Postgres guarantees no row order without an `ORDER BY`, and PostgREST adds
 * none. Two `.range()` calls against an unordered relation may return
 * overlapping or disjoint slices, so a paginated loop without a stable sort key
 * can **duplicate or skip rows** — silently, and only under load. Three loops in
 * this repo shipped that way (`morning-alert`, `weekly-recap-ready`,
 * `weekly-recalc`); `i-see-you-callout` got it right with
 * `.order("id", { ascending: true })`. Making `orderBy` a required parameter
 * with no default is how that mistake becomes unconstructible here.
 *
 * Pick a key that is **unique and immutable** — a primary key. A non-unique key
 * (`date`, `status`) does not fully order the rows, so ties can shuffle between
 * page requests and reintroduce the same skip/duplicate bug.
 *
 * ## RPCs
 *
 * `.order()` / `.range()` are accepted on `/rpc/` set-returning functions, so
 * both helpers work with `() => supabase.rpc(...)`. Whether `db-max-rows` also
 * caps RPC responses could not be settled from here: the only anon-executable
 * set-returning functions on this project are not `SECURITY DEFINER`, so RLS
 * returns 0 rows to `anon` and the probe is inconclusive. It does not change
 * anything — these helpers page unconditionally, which is correct either way
 * (if the cap does not apply, the loop simply ends on the first empty page).
 *
 * @see docs/audit/open_issues.md OI-79
 */

// deno-lint-ignore-file no-explicit-any

/**
 * PostgREST's server-side `db-max-rows` for this project, confirmed live
 * (table above). A response can never exceed this many rows regardless of the
 * requested `Range`.
 */
export const POSTGREST_MAX_ROWS = 1000;

/** Default page size. Sits at the cap: the largest value that is still safe. */
export const DEFAULT_PAGE_SIZE = 1000;

/**
 * Default `.in()` chunk size. Bounds the **request URL**, which is a different
 * constraint from `pageSize` (which bounds the *response*). A uuid costs ~37
 * bytes in `in.(...)`, so 100 ids is ~3.7KB and stays clear of the ~4-8KB URL
 * limits proxies impose. Matches the existing `BATCH_SIZE = 100` precedent in
 * `evaluate-rank-promotions`.
 */
export const DEFAULT_CHUNK_SIZE = 100;

/**
 * Runaway guard. At the default page size this permits 10M rows, far beyond any
 * legitimate cron scan — it exists to turn "PostgREST keeps returning full
 * pages forever" (an unstable sort key, a clock-skewed filter) into a loud
 * failure instead of an Edge Function that runs until the platform kills it.
 */
export const DEFAULT_MAX_PAGES = 10_000;

/** Minimal structural shape we need from a supabase-js query builder. */
interface RangeableBuilder {
  order(column: string, opts: { ascending: boolean }): RangeableBuilder;
  range(from: number, to: number): PromiseLike<{ data: unknown; error: unknown }>;
}

/** One ORDER BY term. */
export interface OrderKey {
  column: string;
  ascending?: boolean;
}

export interface PagedFetchOptions {
  /**
   * REQUIRED. Sort key — must be unique and immutable (a primary key). See the
   * header note on why this has no default.
   *
   * Pass an array to sort by several columns, e.g. to page a "most recent row
   * per user" read while preserving its ordering semantics:
   * `[{ column: "snapshot_date", ascending: false }, { column: "id" }]`.
   * The **last** term must be unique — the earlier ones can tie, and ties
   * without a unique tiebreaker are exactly the unstable-page bug.
   */
  orderBy: string | OrderKey[];
  /**
   * Sort direction for the single-column form. Ignored when `orderBy` is an
   * array (each term carries its own).
   */
  ascending?: boolean;
  /** Rows per request. MUST be <= {@link POSTGREST_MAX_ROWS}; see header note 2. */
  pageSize?: number;
  /** Runaway guard, see {@link DEFAULT_MAX_PAGES}. */
  maxPages?: number;
  /** Prefix for the saturation log line. Defaults to "paged_fetch". */
  label?: string;
}

/** Normalises the `orderBy` union into a non-empty list of ORDER BY terms. */
function orderKeys(opts: PagedFetchOptions): OrderKey[] {
  const bad = () => {
    throw new Error(
      "paged_fetch: `orderBy` is required and must be a non-empty column name " +
        "(or a non-empty array of them). A .range() loop without a stable sort " +
        "key can skip or duplicate rows (OI-79).",
    );
  };

  if (typeof opts.orderBy === "string") {
    if (!opts.orderBy.trim()) bad();
    return [{ column: opts.orderBy, ascending: opts.ascending ?? true }];
  }
  if (!Array.isArray(opts.orderBy) || opts.orderBy.length === 0) bad();
  const keys = (opts.orderBy as OrderKey[]).map((k) => {
    if (!k || typeof k.column !== "string" || !k.column.trim()) bad();
    return { column: k.column, ascending: k.ascending ?? true };
  });
  return keys;
}

function validate(opts: PagedFetchOptions): { pageSize: number; maxPages: number } {
  orderKeys(opts); // throws when the sort key is missing or malformed
  const pageSize = opts.pageSize ?? DEFAULT_PAGE_SIZE;
  if (!Number.isInteger(pageSize) || pageSize < 1) {
    throw new Error(`paged_fetch: pageSize must be a positive integer, got ${pageSize}`);
  }
  if (pageSize > POSTGREST_MAX_ROWS) {
    throw new Error(
      `paged_fetch: pageSize ${pageSize} exceeds PostgREST's db-max-rows ` +
        `(${POSTGREST_MAX_ROWS}). A larger page cannot fetch more rows — the server ` +
        `silently clamps it — so every page costs a full round-trip for at most ` +
        `${POSTGREST_MAX_ROWS} rows while the arithmetic implies more. The loop itself is ` +
        `SAFE at any cap (it advances by rows received and stops only on an empty page), ` +
        `so this is a wrong-configuration guard, not a correctness one. ` +
        `Use a pageSize <= ${POSTGREST_MAX_ROWS} (OI-79).`,
    );
  }
  const maxPages = opts.maxPages ?? DEFAULT_MAX_PAGES;
  if (!Number.isInteger(maxPages) || maxPages < 1) {
    throw new Error(`paged_fetch: maxPages must be a positive integer, got ${maxPages}`);
  }
  return { pageSize, maxPages };
}

/**
 * Reads **every** row matching a query, paging until an EMPTY page arrives.
 *
 * `makeQuery` must return a fresh builder each call — supabase-js builders are
 * single-use thenables, so reusing one across pages does not work. Apply your
 * filters there and let this apply `.order()` and `.range()`:
 *
 * ```ts
 * const rows = await fetchAllPages<{ user_id: string }>(
 *   () => supabase.from("coach_memory").select("user_id").gte("dropout_risk_score", 0.5),
 *   { orderBy: "user_id", label: "re-engagement path A" },
 * );
 * ```
 *
 * Throws on the first page error rather than returning partial rows. That is
 * deliberate: silently proceeding with an incomplete candidate set is the exact
 * failure this module exists to prevent, and a cron tick that cannot read its
 * inputs should fail loudly and retry on the next tick.
 */
export async function fetchAllPages<T>(
  makeQuery: () => unknown,
  opts: PagedFetchOptions,
): Promise<T[]> {
  const { pageSize, maxPages } = validate(opts);
  const keys = orderKeys(opts);
  const label = opts.label ?? "paged_fetch";
  const keyDesc = keys.map((k) => `${k.column}${k.ascending ? "" : " desc"}`).join(", ");

  const all: T[] = [];

  for (let page = 0; ; page++) {
    if (page >= maxPages) {
      throw new Error(
        `paged_fetch[${label}]: exceeded maxPages=${maxPages} (${all.length} rows read). ` +
          `Every page came back full — check that orderBy='${keyDesc}' ends in a unique, ` +
          `immutable column; an unstable sort key can loop forever.`,
      );
    }

    // Offset by rows ACTUALLY received, never by `page * pageSize`. The two
    // agree only while the server serves full pages, and `db-max-rows` is a
    // dashboard setting (Settings -> API -> Max rows), not a platform
    // invariant. Lower it to 500 and the old arithmetic broke completely:
    // page 0 asked 0-999, got 500, and `500 < pageSize` read as end-of-data —
    // so every one of the reads this module was written to fix would silently
    // return 500 rows with error === null. Advancing by `all.length` makes the
    // loop correct for ANY server cap without having to know what it is.
    const from = all.length;
    const to = from + pageSize - 1;

    let q = makeQuery() as RangeableBuilder;
    for (const k of keys) q = q.order(k.column, { ascending: k.ascending ?? true });
    const builder = q.range(from, to);

    const { data, error } = await builder;
    if (error) {
      throw new Error(
        `paged_fetch[${label}]: page ${page} (rows ${from}-${to}) failed: ` +
          `${(error as { message?: string } | null)?.message ?? String(error)}`,
      );
    }

    const rows = (data ?? []) as T[];
    all.push(...rows);

    // Only an EMPTY page proves end-of-data. A SHORT page does not: it is
    // equally the signature of a server cap below `pageSize` (see the offset
    // note above), and treating it as "done" is exactly the silent truncation
    // this module exists to prevent.
    //
    // COST, stated honestly. For `fetchAllPages` this is one extra round-trip
    // per read. For `fetchAllByIds` it is one extra per CHUNK, and with
    // DEFAULT_CHUNK_SIZE = 100 a chunk essentially never fills a 1000-row
    // page — so the confirming request lands on ~every chunk, not on a rare
    // boundary. 12 chunked call sites; at ~10k PRO users protein-gap-alert
    // goes from roughly 300 to 600 sequential round-trips per tick. Accepted
    // deliberately: these are daily cron jobs where wall-clock is cheap, and
    // the alternative is a read that silently returns half its rows with
    // error === null. If round-trips ever become the constraint, learn the
    // server's real page size once per process instead. (Corrected after
    // round-2 review — the earlier note claimed "the same one the
    // exact-multiple case already paid", true of fetchAllPages and NOT of the
    // chunked path that dominates.)
    if (rows.length === 0) break;
  }

  return all;
}

/**
 * Reads every row for a set of ids, chunking the `.in()` list **and** paging
 * within each chunk.
 *
 * Chunking alone is not enough, and that distinction is the whole point of this
 * function. `evaluate-rank-promotions` already had a `fetchInChunks` helper that
 * split `userIds` into batches of 100 — but a chunk bounds the *request*, not
 * the *response*. One 100-id chunk against a table holding N rows per user
 * returns 100xN rows, so it truncates at 10 rows/user no matter how small the
 * chunk is. This pages inside each chunk, which bounds both.
 *
 * ```ts
 * const logs = await fetchAllByIds<{ user_id: string }>(
 *   (chunk) => supabase.from("nutrition_logs")
 *                      .select("user_id, total_protein")
 *                      .eq("date", todayIST)
 *                      .in("user_id", chunk),
 *   proUserIds,
 *   { orderBy: "id", label: "protein-gap-alert nutrition" },
 * );
 * ```
 */
export async function fetchAllByIds<T>(
  makeQuery: (idChunk: string[]) => unknown,
  ids: string[],
  opts: PagedFetchOptions & { chunkSize?: number },
): Promise<T[]> {
  validate(opts);

  const chunkSize = opts.chunkSize ?? DEFAULT_CHUNK_SIZE;
  if (!Number.isInteger(chunkSize) || chunkSize < 1) {
    throw new Error(`paged_fetch: chunkSize must be a positive integer, got ${chunkSize}`);
  }

  if (ids.length === 0) return [];

  const all: T[] = [];
  for (let i = 0; i < ids.length; i += chunkSize) {
    const chunk = ids.slice(i, i + chunkSize);
    const rows = await fetchAllPages<T>(() => makeQuery(chunk), {
      ...opts,
      label: `${opts.label ?? "paged_fetch"} chunk@${i}`,
    });
    all.push(...rows);
  }
  return all;
}

/**
 * notification_prefs.ts — the single server-side reader of a user's
 * notification preferences (Unit E).
 *
 * ⚠ SOURCE OF TRUTH MOVED (OI-98 / e4a1b7, 2026-08-26)
 * ----------------------------------------------------
 * The primary source is now `user_preferences.notification_preferences` — one
 * row per user, written by partial-column upsert. Everything below about
 * snapshots describes the FALLBACK, which is read only for users the column
 * does not answer for, and which exists solely so client and server deploys do
 * not have to be ordered. It is retired once APK +39 adoption makes it dead
 * weight.
 *
 * WHY IT MOVED. `snapshot_json` is a DERIVED document: rebuilt wholesale from
 * Hive on every write and REPLACED, not merged, on upsert. That is correct for
 * regenerable data and wrong for user intent, which is the only copy in
 * existence. Two failures followed, both measured live on 2026-08-26:
 *   1. A reinstalled device — its Hive box empty, which is indistinguishable
 *      from "everything enabled" — pushed an all-enabled default that REPLACED
 *      the server's stored copy. The choice was destroyed, not merely unread.
 *   2. FOUR Edge Functions write that row (`daily-snapshot`, `rolling-context`,
 *      `future-prediction`, `beat-my-coach`) and the last three create a
 *      preference-less row when the day has none. Since every reader takes the
 *      newest row with no fall-through, 3 of the 5 users who had ever stored a
 *      preference were being ignored outright.
 * A column has one writer per concept, survives its siblings' upserts, and has
 * no "newest row" to lose — so neither failure is representable.
 *
 * THE RULE: ABSENT ⇒ SEND (decision N2)
 * ------------------------------------
 * A missing key, a missing snapshot, a failed query, a malformed value — every
 * one of them means SEND. Only a literal `enabled === false` silences a push.
 * Nobody loses a notification to a sync gap or a transient database error; the
 * cost of the opposite default is a user who turned something off and can never
 * work out why it still arrives.
 *
 * WHY latest-desc AND NOT today-pinned
 * ------------------------------------
 * The obvious implementation pins `snapshot_date` to today. It is inert.
 * Measured against live data: 91 snapshot rows across 17 users, exactly **1**
 * row for today, only 3 users fresh within three days, and the stalest user's
 * newest row was two months old. A today-pinned read would therefore find
 * nothing for 16 of 17 users and fall through to SEND — i.e. the toggles would
 * still do nothing, while looking implemented.
 *
 * It is worse than merely ineffective for `re-engagement`, whose targets are BY
 * DEFINITION people who have not opened the app recently. Their snapshot can
 * never be today's. A today-pinned guard there is not "usually inert", it is
 * guaranteed inert.
 *
 * So: order by snapshot_date DESC and keep the FIRST row per user — the user's
 * most recent known preferences, however old. Shape copied from
 * `weekly-recap-ready/index.ts:163-185`, which already had it right.
 *
 * WHY BATCHED
 * -----------
 * One query per run, not one per user. `re-engagement` already runs a
 * multi-query loop per candidate; adding a per-user `.single()` there would
 * multiply the round-trips on the function with the largest candidate set.
 *
 * WHY PAGED (OI-79)
 * -----------------
 * The batched read used to be a bare `.in(userIds)`, which PostgREST caps at
 * `db-max-rows` (1000) — returning HTTP 200 with `error === null`, so a clipped
 * result is indistinguishable from a complete one. `user_daily_snapshots` holds
 * MANY rows per user (97 rows across 17 users live, ~5.7 each), so the cap bites
 * at roughly 175 users, not 1000.
 *
 * That interacts badly with everything above. Rows arrive `snapshot_date DESC`
 * and the first row per user wins, so truncation removes the TAIL — precisely
 * the users whose newest snapshot is oldest. Under the ABSENT ⇒ SEND rule those
 * users' preferences then read as absent, and **every toggle they set is
 * silently ignored**. That is the same "toggles look implemented but do nothing"
 * failure this file's own header was written to prevent, reached by a different
 * route.
 *
 * `fetchAllByIds` fixes it and preserves the semantics: chunking is BY user id,
 * so all of one user's rows stay in a single chunk, and the compound sort key
 * (`snapshot_date DESC`, then `id`) keeps the global order stable across pages —
 * so "first row per user wins = most recent" still holds. `id` is the tiebreaker
 * because `snapshot_date` is not unique and a non-unique page key can shuffle
 * ties between requests.
 */

import { fetchAllByIds } from "./paged_fetch.ts";

// deno-lint-ignore no-explicit-any
type SupabaseLike = any;

/** Per-user preference maps, keyed by user_id. */
export type PrefsByUser = Map<string, Record<string, unknown>>;

/**
 * [fetchNotificationPrefs]'s result, plus whether the lookup could actually be
 * PERFORMED.
 *
 * WHY THIS EXISTS — "absent" and "could not ask" are different facts.
 * `PrefsByUser` alone cannot tell them apart: a user missing from the map means
 * either "this user has set no preferences" (a real answer, and ABSENT => SEND
 * correctly applies) or "every query failed" (no answer at all). Collapsing the
 * two is fine for the six callers that want N2's fail-safe unconditionally, and
 * NOT fine for `workout-window-closing`, which deliberately skips a user it
 * cannot verify rather than risk a nudge they switched off.
 *
 * `degraded` is true only when a source THREW. A source that returns zero rows
 * is an answer, not a failure.
 */
export interface PrefsLookup {
  prefs: PrefsByUser;
  degraded: boolean;
}

/**
 * Most-recent notification preferences for each of [userIds].
 *
 * Returns an EMPTY map on any failure — callers then send to everyone, which is
 * the fail-safe direction (N2). Never throws: an exception escaping here would
 * abort a whole cron run for a preferences lookup.
 */
export async function fetchNotificationPrefs(
  client: SupabaseLike,
  userIds: string[],
): Promise<PrefsByUser> {
  return (await fetchNotificationPrefsDetailed(client, userIds)).prefs;
}

/**
 * As [fetchNotificationPrefs], but also reports whether the lookup could be
 * performed at all — see [PrefsLookup].
 *
 * Callers that want N2's unconditional fail-safe should keep using
 * [fetchNotificationPrefs]; this variant is for a caller whose correct
 * behaviour on "could not ask" differs from its behaviour on "no preferences
 * set".
 */
export async function fetchNotificationPrefsDetailed(
  client: SupabaseLike,
  userIds: string[],
): Promise<PrefsLookup> {
  const out: PrefsByUser = new Map();
  let degraded = false;
  // An empty input is a complete answer to a question about nobody, not a
  // failure — degraded stays false.
  if (!userIds || userIds.length === 0) return { prefs: out, degraded };

  // ── PRIMARY: user_preferences.notification_preferences (OI-98 / e4a1b7) ──
  //
  // The preferences used to live inside `user_daily_snapshots.snapshot_json`,
  // which is a DERIVED document: replaced wholesale on every write, by four
  // different writers, with the readers below taking only the NEWEST row and
  // never falling through. Three of five users with a stored preference were
  // being ignored because a cron had created that day's row before their
  // device wrote one. `user_preferences` is one row per user, written by
  // partial-column upsert, so none of that applies.
  //
  // STILL PAGED. "One row per user" does not make `.in()` safe — a bare `.in()`
  // is clipped at PostgREST's db-max-rows with HTTP 200 and `error === null`,
  // which is the OI-79 failure this file's header documents. One row per user
  // moves the cliff from ~175 users to 1000; it does not remove it, and
  // truncation still fails toward SEND. `user_id` is the sort key and is unique
  // here (it is the upsert's conflict target), which is what `orderBy` requires.
  const resolved = new Set<string>();
  try {
    const rows = await fetchAllByIds<Record<string, unknown>>(
      (chunk) =>
        client
          .from("user_preferences")
          .select("user_id, notification_preferences")
          .in("user_id", chunk),
      userIds,
      { orderBy: "user_id", label: "notification_prefs_column" },
    );

    for (const row of (rows ?? []) as Record<string, unknown>[]) {
      const uid = row.user_id as string | undefined;
      if (!uid) continue;
      const prefs = row.notification_preferences;
      // NULL means "no record for this user" and must fall through to the
      // snapshot during the cutover. A non-null value — including `{}` — is a
      // real record and is authoritative, so it does NOT fall through.
      if (prefs === null || prefs === undefined) continue;
      resolved.add(uid);
      out.set(
        uid,
        typeof prefs === "object" && !Array.isArray(prefs)
          ? prefs as Record<string, unknown>
          : {},
      );
    }
  } catch (err) {
    // Same contract as the snapshot path below: never throw, degrade to the
    // fallback (and ultimately to SEND). A column read that fails must not
    // abort a whole cron run.
    console.error("[notification_prefs] column read failed, falling back:", err);
    degraded = true;
  }

  // ── FALLBACK: the legacy snapshot key ──
  //
  // Read ONLY for users the column did not answer for. This is what removes the
  // deploy-ordering constraint between client and server: a device that has not
  // yet synced the new column keeps being honoured exactly as before. It is
  // retired once +39 adoption makes it dead weight — tracked on the OI board
  // with that trigger, not left to be noticed.
  const unresolved = userIds.filter((id) => !resolved.has(id));
  if (unresolved.length === 0) return { prefs: out, degraded };

  try {
    const data = await fetchAllByIds<Record<string, unknown>>(
      (chunk) =>
        client
          .from("user_daily_snapshots")
          .select("user_id, snapshot_json")
          .in("user_id", chunk),
      unresolved,
      {
        // snapshot_date DESC preserves "first row per user wins = most recent";
        // `id` is the unique tiebreaker that makes the paging stable (OI-79).
        orderBy: [
          { column: "snapshot_date", ascending: false },
          { column: "id", ascending: true },
        ],
        label: "notification_prefs",
      },
    );

    for (const row of (data ?? []) as Record<string, unknown>[]) {
      const uid = row.user_id as string | undefined;
      if (!uid || out.has(uid)) continue; // first row wins = most recent
      const snap = (row.snapshot_json ?? {}) as Record<string, unknown>;
      const prefs = snap.notification_preferences;
      out.set(
        uid,
        prefs && typeof prefs === "object" && !Array.isArray(prefs)
          ? prefs as Record<string, unknown>
          : {},
      );
    }
    return { prefs: out, degraded };
  } catch (err) {
    // Catches BOTH a transport-level rejection (DNS, reset, timeout before any
    // HTTP response) AND a query error, which `fetchAllByIds` now raises rather
    // than returning as `{ error }`. Either way this degrades to "send to
    // everyone" instead of aborting the whole cron run — the N2 fail-safe
    // direction, and the reason this function's contract is "never throws".
    // Same reasoning as _shared/subscription.ts.
    console.error("[notification_prefs] failed, defaulting to SEND:", err);
    return { prefs: out, degraded: true };
  }
}

/**
 * True when [key] should be SENT to [userId].
 *
 * Only an explicit `enabled === false` returns false. Absent user, absent key,
 * non-object entry, non-boolean `enabled` — all send.
 */
export function isNotificationEnabled(
  prefs: PrefsByUser,
  userId: string,
  key: string,
): boolean {
  const userPrefs = prefs.get(userId);
  if (!userPrefs) return true;

  const entry = userPrefs[key];
  if (!entry || typeof entry !== "object" || Array.isArray(entry)) return true;

  return (entry as Record<string, unknown>).enabled !== false;
}
